"package com.example.educationpath.ui.screens\n\nimport androidx.compose.foundation.clickable\nimport androidx.compose.foundation.layout.Column\nimport androidx.compose.foundation.layout.padding\nimport androidx.compose.material3.Card\nimport androidx.compose.material3.CardDefaults\nimport androidx.compose.material3.MaterialTheme\nimport androidx.compose.material3.Text\nimport androidx.compose.runtime.Composable\nimport androidx.compose.runtime.collectAsState\nimport androidx.compose.runtime.getValue\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.unit.dp\nimport androidx.hilt.navigation.compose.hiltViewModel\nimport androidx.lifecycle.viewmodel.compose.viewModel\nimport com.example.educationpath.data.model.Path\import com.example.educationpath.ui.viewmodel.PathListViewModel\nimport com.example.educationpath.ui.viewmodel.PathListViewModelFactory\n\n@Composable\nfun PathListScreen(viewModel: PathListViewModel = hiltViewModel<PathListViewModel>()) {\n    val paths by viewModel.paths.collectAsState()\n\n    Column(modifier = Modifier.padding(16.dp)) {\n        Text(\"Your Educational Paths\", style = MaterialTheme.typography.headlineMedium)\n        // ... existing code ...\n        paths.forEach { path ->\n            PathItem(path = path) {\n                // Action to navigate to PathDetailScreen with path.id\n            }\n            // ... existing code ...\n        }\n        // Floating action button to add new path\n    }\n}\n\n@Composable\nfun PathItem(path: Path, onClick: () -> Unit) {\n    Card(onClick = onClick, modifier = Modifier.padding(vertical = 8.dp))\n    {\n        Text(text = path.name, style = MaterialTheme.typography.titleLarge)\n        Text(text = path.description ?: \"No description provided.\", style = MaterialTheme.typography.bodyMedium)\n    }\n}\n"